def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    h = max(0, int(horizon))
    if h == 0:
        return []
    y = []
    for v in history:
        try:
            x = float(v)
            if math.isfinite(x):
                y.append(x)
        except (TypeError, ValueError):
            pass
    if not y:
        return [0.0] * h
    p = 24 if 'hour' in frequency.lower() else (7 if 'day' in frequency.lower() else 1)
    if len(y) < p:
        return [float(statistics.median(y[-min(5, len(y)):]))] * h
    def predict(train, n, alpha, beta):
        out = []
        for k in range(n):
            z = train + out
            phase = len(z) % p
            same = [z[j] for j in range(phase, len(z), p)]
            recent = same[-1]
            center = statistics.median(same[-3:])
            shifts = []
            for d in range(1, min(4, len(z) // p)):
                a = z[-d * p:-(d - 1) * p if d > 1 else None]
                b = z[-(d + 1) * p:-d * p]
                if len(a) == p and len(b) == p:
                    shifts.append(statistics.median([a[i] - b[i] for i in range(p)]))
            shift = statistics.median(shifts) if shifts else 0.0
            scale = statistics.median([abs(q - statistics.median(z[-min(3 * p, len(z)):])) for q in z[-min(3 * p, len(z)):]])
            shift = max(-scale, min(scale, shift))
            out.append(float(alpha * recent + (1.0 - alpha) * center + beta * shift))
        return out
    def smape(a, b):
        vals = [200.0 * abs(x - q) / (abs(x) + abs(q)) for x, q in zip(a, b) if abs(x) + abs(q) > 1e-12]
        return sum(vals) / len(vals) if vals else 0.0
    choices = [(a, b) for a in (0.0, 0.25, 0.5, 0.75, 1.0) for b in (0.0, 0.25, 0.5)]
    folds = []
    for back in (3, 2, 1):
        cut = len(y) - back * p
        if cut >= 2 * p:
            folds.append((y[:cut], y[cut:cut + p]))
    if folds:
        scored = []
        for a, b in choices:
            errors = [smape(actual, predict(train, len(actual), a, b)) for train, actual in folds]
            scored.append((statistics.median(errors), a, b))
        _, alpha, beta = min(scored)
    else:
        alpha, beta = 1.0, 0.0
    return predict(y, h, alpha, beta)
